interface TechIconsMapProps {
  [key: string]: React.FC<TechIconProps>;
}

export const techIconsMap: TechIconsMapProps = {
  JavaScript: JavaScriptIcon,
  Python: PythonIcon,
  'Node.js': NodeIcon,
  Golang: GoIcon,
  PHP: PHPIcon,
  PostgreSQL: PostgreSQLIcon,
  Ruby: RubyIcon,
  Redis: RedisIcon,
  MongoDB: MongoDBIcon,
  Docker: DockerIcon,
  Kubernetes: KubernetesIcon,
  Kafka: KafkaIcon,
  RabbitMQ: RabbitMQIcon,
  Claude: ClaudeIcon,
  Cursor: CursorIcon,
  Grafana: GrafanaIcon,
  Manus: ManusIcon,
  'CI/CD': CiCdIcon,
  Recraft: RecraftIcon,
};

export function getTechIcon(techName: string): React.FC<TechIconProps> {
  return techIconsMap[techName];
}
